/** Normalize an agent directory or display name into an env var prefix. */
export function envPrefixFromName(name) {
    return name
        .trim()
        .replace(/[^A-Za-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "")
        .toUpperCase();
}
/**
 * The prefix stored on a channel. A blank prefix is `""`. Any other prefix
 * is the normalized name. Callers build env names with {@link envName} from
 * this result, so the stored prefix and the names stay the same.
 */
export function storedEnvPrefix(prefix) {
    if (prefix === undefined || prefix.trim() === "") {
        return "";
    }
    return envPrefixFromName(prefix);
}
/** Full env name for a stored prefix. An empty prefix keeps the suffix. */
export function envName(envPrefix, suffix) {
    return envPrefix === "" ? suffix : `${envPrefix}_${suffix}`;
}
